  let channels=[],visible=[],current=null,selected=null,highlightedKey='',renderFrame=0,sourceUrl=FEEDS[0].url,sourceTitle=FEEDS[0].name,activeLanguage='All languages',activeCategory='All categories',hls=null,noticeTimer,epg=new Map(),epgAliases=new Map(),epgName='',originalChannelOrder=[];
