  function persistGeometry(){const shell=ui.tvShell.getBoundingClientRect();uiSettings.positions||={};uiSettings.panels||={};for(const el of [ui.guide,ui.controls,ui.bugChannel,ui.sourceButton]){if(!el.style.left&&!el.style.top&&!el.style.width&&!el.style.height)continue;const r=el.getBoundingClientRect(),computed=getComputedStyle(el);uiSettings.positions[el.id]={left:`${r.left/shell.width*100}%`,top:`${r.top/shell.height*100}%`,width:`${r.width/shell.width*100}%`,height:`${r.height/shell.height*100}%`};uiSettings.panels[el.id]={...(uiSettings.panels[el.id]||{}),width:Math.round(r.width/shell.width*100),height:Math.round(r.height/shell.height*100),opacity:Math.round(Number(computed.opacity)*100),radius:parseInt(computed.borderRadius,10)||0};}localStorage.setItem(KEYS.layout,JSON.stringify(uiSettings));}
