  function installPanelMove(el,handle){handle.addEventListener('pointerdown',e=>{if(!ui.editLayout.checked||e.button!==0||(el.id!=='sourceButton'&&e.target.closest('button,input,select')))return;e.preventDefault();const shell=ui.tvShell.getBoundingClientRect(),box=el.getBoundingClientRect(),dx=e.clientX-box.left,dy=e.clientY-box.top;const move=ev=>{el.style.left=`${Math.max(0,Math.min(shell.width-el.offsetWidth,ev.clientX-shell.left-dx))}px`;el.style.top=`${Math.max(0,Math.min(shell.height-el.offsetHeight,ev.clientY-shell.top-dy))}px`;el.style.right='auto';el.style.bottom='auto';};const done=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',done);saveSettings();};window.addEventListener('pointermove',move);window.addEventListener('pointerup',done);});}
