  function filtered(){let list=channels.filter(c=>!channelPrefs.hidden?.includes(key(c))).filter(c=>activeLanguage==='All languages'||(c.language||'Not tagged').toLowerCase()===activeLanguage.toLowerCase()).filter(c=>activeCategory==='All categories'||channelCategory(c).toLowerCase()===activeCategory.toLowerCase());const q=ui.search.value.trim().toLowerCase();if(q)list=list.filter(c=>c.name.toLowerCase().includes(q));if(current&&!list.some(c=>key(c)===key(current)))list.unshift(current);return list;}
