  function normalizeNumberName(name){return String(name||'').toLowerCase().replace(/\s*\((?:360p|396p|576p|720p|1080p|1440p|2160p|4k|uhd)\)\s*$/i,'').replace(/\b(?:360p|396p|576p|720p|1080p|1440p|2160p|4k|uhd)\b/gi,'').replace(/[^a-z0-9]/g,'');}
