  function renderSettingsChannels(){if(!ui.settingsChannelRows)return;let list=channels.slice();if(settingsChannelFilter==='favorites')list=list.filter(c=>channelPrefs.favorites.includes(key(c)));ui.settingsChannelRows.innerHTML=list.map((c,i)=>{const k=key(c),on=settingsSelectedKey===k;return `<button class="settings-channel-row${on?' selected':''}" data-settings-channel="${esc(k)}"><span><input type="checkbox" tabindex="-1" ${on?'checked':''}></span><b>${displayChannelNumber(c,channels.indexOf(c))}</b><strong>${esc(c.displayName||c.name)}${channelPrefs.hidden?.includes(k)?' · HIDDEN':''}</strong><span>↕</span><span>${channelPrefs.favorites.includes(k)?'♥':'♡'}</span></button>`;}).join('');ui.settingsChannelRows.querySelectorAll('[data-settings-channel]').forEach(row=>row.addEventListener('click',()=>{settingsSelectedKey=row.dataset.settingsChannel;renderSettingsChannels();}));}
